package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.auth.model.entity.UserRole;
import dustin.cex.domains.bitcoin.*;
import dustin.cex.domains.monitoring.*;
import dustin.cex.domains.valuation.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/** 실제 금융 입력·탐지·사건·의견을 새 PG에서 연결한다. 사건 생성은 고객 자격·제한·사용 가능 잔액을 바꾸지 않는다. */
class DepositMonitoringCaseIntegrationTest extends EddTestSupport {
    @DynamicPropertySource static void bitcoin(DynamicPropertyRegistry r){r.add("bitcoin.rpc-url",()->"http://127.0.0.1:1");r.add("bitcoin.rpc-user",()->"isolated");r.add("bitcoin.rpc-password",()->"isolated-monitoring-case-password-at-least-32-bytes");r.add("bitcoin.wallet",()->"cex_watch");r.add("bitcoin.network",()->"REGTEST");r.add("bitcoin.processing.enabled",()->false);r.add("valuation.upbit.enabled",()->true);}
    @Autowired DepositMonitoringService monitoring;
    @Autowired DepositMonitoringReview review;
    @Autowired DepositMonitoringInvestigations investigations;
    @Autowired BitcoinPendingDepositService pending;
    @Autowired BitcoinDepositQualificationService qualification;
    @Autowired dustin.cex.domains.ledger.LedgerService ledger;
    @Autowired BitcoinKrwPriceService prices;
    @MockitoSpyBean DepositMonitoringCases cases;
    @MockitoBean BitcoinKrwPriceClient price;
    @MockitoBean BitcoinDepositReader reader;
    @BeforeEach void original(){ledger.initializeOpening();when(price.read()).thenAnswer(call->{Instant now=Instant.ofEpochMilli(Instant.now().toEpochMilli());String payload=json.writeValueAsString(List.of(Map.of("market","KRW-BTC","trade_price",1700000,"trade_timestamp",now.toEpochMilli(),"timestamp",now.toEpochMilli())));return new BitcoinKrwPriceClient.Quote(new BigDecimal("1700000"),now,now,now,now,payload,sha(payload));});assertEquals("SUCCESS",prices.refresh().status());clearInvocations(price);}
    BitcoinDepositFixtures.Seed deposit(long owner){var r=BitcoinDepositFixtures.seed(jdbc,json,owner,Instant.now());BitcoinDepositFixtures.observe(jdbc,json,manager,qualification,r,false);pending.recognize(r.id());return r;}
    DepositMonitoringService.Assessment inputs(long owner,int n){DepositMonitoringService.Assessment last=null;for(int i=0;i<n;i++){deposit(owner);last=monitoring.processNext().orElseThrow();}return last;}
    UUID caseId(){return jdbc.queryForObject("SELECT case_id FROM deposit_monitoring_case_heads WHERE user_id=?",UUID.class,customer.getId());}
    long count(String table){return jdbc.queryForObject("SELECT count(*) FROM "+table,Long.class);}
    void cause(String text,Runnable work){Throwable error=assertThrows(RuntimeException.class,work::run);while(error.getCause()!=null)error=error.getCause();assertTrue(error.getMessage().contains(text),error.toString());}
    @AfterEach void noFinancialChange(){verifyNoInteractions(engine,producer,reader,price);assertEquals(0,count("user_balances"));assertEquals(0,jdbc.queryForObject("SELECT coalesce(sum(delta),0) FROM ledger_entries WHERE asset='BTC'",BigDecimal.class).signum());assertFalse(users.findById(customer.getId()).orElseThrow().isTradingRestricted());}
    @Test void firstSignalCreatesOneCaseAndFurtherSignalsJoinIt(){inputs(customer.getId(),4);assertEquals(0,count("deposit_monitoring_cases"));var fifth=inputs(customer.getId(),1);UUID id=caseId();var sixth=inputs(customer.getId(),1);assertEquals(id,caseId());assertEquals(1,count("deposit_monitoring_cases"));assertEquals(2,count("deposit_monitoring_case_assessments"));var result=cases.members(maker.user().getId(),maker.sid(),id,null);assertEquals("OPEN",result.investigation().status());assertEquals(fifth.id(),result.investigation().firstAssessmentId());assertEquals(List.of(sixth.id(),fifth.id()),result.items().stream().map(DepositMonitoringCases.Member::assessmentId).toList());assertEquals(id,new TransactionTemplate(manager).execute(t->review.read(customer.getId())).caseId());}
    @Test void incompleteInputDoesNotInventAReviewSignalCase(){doThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"격리 가격 실패")).when(price).read();assertEquals("FAILED",prices.refresh().status());clearInvocations(price);assertEquals("INCOMPLETE",inputs(customer.getId(),1).result().outcome());assertEquals(0,count("deposit_monitoring_cases"));assertNull(new TransactionTemplate(manager).execute(t->review.read(customer.getId())).caseId());}
    @Test void duplicateLinkReturnsSameCaseWithoutNewMembershipOrAudit(){var a=inputs(customer.getId(),5);UUID id=caseId();for(int i=0;i<2;i++)assertEquals(id,new TransactionTemplate(manager).execute(t->cases.link(a.id())));assertEquals(1,count("deposit_monitoring_case_assessments"));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE action='MONITORING_CASE_ASSESSMENT_LINKED'",Long.class));assertThrows(org.springframework.transaction.IllegalTransactionStateException.class,()->cases.link(a.id()));}
    @Test void concurrentProcessingKeepsOneCustomerCase()throws Exception{for(int i=0;i<6;i++)deposit(customer.getId());for(int i=0;i<4;i++)monitoring.processNext().orElseThrow();var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<Object> call=()->{assertTrue(start.await(5,TimeUnit.SECONDS));return monitoring.processNext();};var a=pool.submit(call);var b=pool.submit(call);start.countDown();a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);}while(monitoring.processNext().isPresent()){}assertEquals(1,count("deposit_monitoring_cases"));assertEquals(2,count("deposit_monitoring_case_assessments"));assertEquals(6,count("deposit_monitoring_assessments"));}
    @Test void differentCustomersNeverShareAnInvestigation(){inputs(customer.getId(),5);UUID first=caseId();var other=users.saveAndFlush(dustin.cex.domains.auth.model.entity.User.builder().email(UUID.randomUUID()+"@test.invalid").passwordHash(hash).build());inputs(other.getId(),5);UUID second=jdbc.queryForObject("SELECT case_id FROM deposit_monitoring_case_heads WHERE user_id=?",UUID.class,other.getId());assertNotEquals(first,second);assertEquals(2,count("deposit_monitoring_cases"));assertEquals(1,cases.members(maker.user().getId(),maker.sid(),first,null).items().size());}
    @Test void caseAuditFailureRollsBackSignalButKeepsEarlierPositions(){inputs(customer.getId(),4);deposit(customer.getId());doThrow(new IllegalStateException("격리 사건 감사 실패")).when(audit).record(isNull(),eq("MONITORING_CASE_ASSESSMENT_LINKED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,monitoring::processNext);assertEquals(4,count("deposit_monitoring_assessments"));assertEquals(0,count("deposit_monitoring_cases"));assertEquals(5,count("bitcoin_pending_deposits"));assertNotNull(jdbc.queryForObject("SELECT lease_id FROM deposit_monitoring_jobs WHERE user_id=?",UUID.class,customer.getId()));doCallRealMethod().when(audit).record(isNull(),eq("MONITORING_CASE_ASSESSMENT_LINKED"),anyString(),anyString(),anyString());jdbc.update("UPDATE deposit_monitoring_jobs SET lease_until=clock_timestamp()-interval '1 second' WHERE user_id=?",customer.getId());assertEquals("REVIEW_REQUIRED",monitoring.processNext().orElseThrow().result().outcome());assertEquals(1,count("deposit_monitoring_cases"));}
    @Test void omittedCaseAuditIsRejectedAtCommit(){inputs(customer.getId(),4);deposit(customer.getId());doNothing().when(audit).record(isNull(),eq("MONITORING_CASE_ASSESSMENT_LINKED"),anyString(),anyString(),anyString());cause("조사 사건의 신호 연결에는 해당 원본의 필수 감사가 필요합니다",()->monitoring.processNext());assertEquals(4,count("deposit_monitoring_assessments"));assertEquals(0,count("deposit_monitoring_cases"));assertEquals(5,count("bitcoin_pending_deposits"));}
    @Test void omittedCaseLinkCannotCommitASeeminglyCompleteSignal(){inputs(customer.getId(),4);deposit(customer.getId());DepositMonitoringCases target=org.springframework.test.util.AopTestUtils.getUltimateTargetObject(cases);doReturn(UUID.randomUUID()).when(target).link(any());cause("새 거래 검토 신호는 조사 사건 연결과 함께 확정해야 합니다",()->monitoring.processNext());assertEquals(4,count("deposit_monitoring_assessments"));assertEquals(0,count("deposit_monitoring_cases"));assertEquals(5,count("bitcoin_pending_deposits"));}
    @Test void operatorsApproversAndAuditorsCanReadMinimumCaseMetadata()throws Exception{inputs(customer.getId(),5);var auditor=account(UserRole.AUDITOR);for(var actor:List.of(maker,checker,auditor)){mvc.perform(get("/api/admin/monitoring-cases").header("Authorization","Bearer "+actor.access())).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andExpect(jsonPath("$[0].status").value("OPEN")).andExpect(jsonPath("$[0].assurance").value(DepositMonitoringCases.ASSURANCE));mvc.perform(get("/api/admin/monitoring-cases/"+caseId()).header("Authorization","Bearer "+actor.access())).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].cursor").isString()).andExpect(jsonPath("$.items[0].notes").doesNotExist());}}
    @Test void customerAnonymousAndExtraMethodsCannotProbeCases()throws Exception{inputs(customer.getId(),5);for(UUID id:List.of(caseId(),UUID.randomUUID())){String path="/api/admin/monitoring-cases/"+id;mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).header("Authorization","Bearer "+customerAccess)).andExpect(status().isForbidden());mvc.perform(post(path).header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());mvc.perform(get(path+"/extra").header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());}}
    @Test void staleOrRevokedOperatorCannotReadEvenKnownCase(){inputs(customer.getId(),5);UUID id=caseId();jdbc.update("UPDATE refresh_tokens SET mfa_verified_at=mfa_verified_at-interval '6 minutes' WHERE session_id=?",maker.sid());assertEquals(403,assertThrows(ResponseStatusException.class,()->cases.members(maker.user().getId(),maker.sid(),id,null)).getStatusCode().value());jdbc.update("UPDATE users SET enabled=false WHERE id=?",checker.user().getId());assertEquals(403,assertThrows(ResponseStatusException.class,()->cases.list(checker.user().getId(),checker.sid(),0)).getStatusCode().value());}
    @Test void caseMemberLinksReachExistingEvidenceAndEncryptedOpinions(){inputs(customer.getId(),5);var member=cases.members(maker.user().getId(),maker.sid(),caseId(),null).items().getFirst();var view=investigations.inspect(maker.user().getId(),maker.sid(),member.receiptId(),member.assessmentId());var note=investigations.record(maker.user().getId(),maker.sid(),member.receiptId(),member.assessmentId(),new DepositMonitoringInvestigations.Write(view.viewId(),UUID.randomUUID(),DepositMonitoringInvestigations.Finding.REQUIRES_FURTHER_REVIEW,"반복 송금의 추가 자료를 확인한다"));assertEquals(1,cases.members(checker.user().getId(),checker.sid(),caseId(),null).items().getFirst().observations());assertEquals(note.id(),investigations.observations(checker.user().getId(),checker.sid(),member.receiptId(),member.assessmentId(),0).getFirst().id());assertEquals("OPEN",cases.list(checker.user().getId(),checker.sid(),0).getFirst().status());}
    @Test void thirtySignalsHaveBoundedCursorPagesWithoutDuplicates(){inputs(customer.getId(),34);var first=cases.members(maker.user().getId(),maker.sid(),caseId(),null);assertEquals(30,first.investigation().signalCount());assertEquals(25,first.items().size());assertNotNull(first.nextBefore());var second=cases.members(maker.user().getId(),maker.sid(),caseId(),Long.parseLong(first.nextBefore()));assertEquals(5,second.items().size());assertNull(second.nextBefore());var ids=new HashSet<UUID>();first.items().forEach(m->assertTrue(ids.add(m.assessmentId())));second.items().forEach(m->assertTrue(ids.add(m.assessmentId())));assertEquals(30,ids.size());assertEquals(400,assertThrows(ResponseStatusException.class,()->cases.members(maker.user().getId(),maker.sid(),caseId(),0L)).getStatusCode().value());assertEquals(400,assertThrows(ResponseStatusException.class,()->cases.list(maker.user().getId(),maker.sid(),-1)).getStatusCode().value());}
    @Test void historicalCaseRemainsVisibleWhenCustomerIsDisabled(){inputs(customer.getId(),5);var user=users.findById(customer.getId()).orElseThrow();user.setEnabled(false);users.saveAndFlush(user);assertEquals(caseId(),cases.list(maker.user().getId(),maker.sid(),0).getFirst().id());assertEquals(1,cases.members(maker.user().getId(),maker.sid(),caseId(),null).items().size());}
    @Test void databaseRejectsWrongCustomerPolicyAndBlankCase(){inputs(customer.getId(),5);var first=cases.members(maker.user().getId(),maker.sid(),caseId(),null).items().getFirst();cause("거래 조사 사건과 실제 고객·정책·검토 신호가 다릅니다",()->jdbc.update("INSERT INTO deposit_monitoring_cases(id,user_id,policy_id,first_assessment_id) VALUES(?,?,?,?)",UUID.randomUUID(),customer.getId(),"WRONG_POLICY",first.assessmentId()));cause("거래 조사 사건과 실제 고객·정책·검토 신호가 다릅니다",()->jdbc.update("INSERT INTO deposit_monitoring_cases(id,user_id,policy_id,first_assessment_id) SELECT ?,?,policy_id,first_assessment_id FROM deposit_monitoring_cases WHERE id=?",UUID.randomUUID(),maker.user().getId(),caseId()));cause("새 거래 조사 사건은 현재 위치와 첫 신호 연결을 함께 확정해야 합니다",()->new TransactionTemplate(manager).executeWithoutResult(t->jdbc.update("INSERT INTO deposit_monitoring_cases(id,user_id,policy_id,first_assessment_id) SELECT ?,user_id,policy_id,first_assessment_id FROM deposit_monitoring_cases WHERE id=?",UUID.randomUUID(),caseId())));assertEquals(1,count("deposit_monitoring_cases"));}
    @Test void financialSourceHashCannotBeSubstitutedOnMembership(){inputs(customer.getId(),5);cause("조사 사건의 신호 연결과 실제 고객·정책·입력 근거가 다릅니다",()->jdbc.update("INSERT INTO deposit_monitoring_case_assessments(case_id,assessment_id,input_cursor,source_hash) SELECT case_id,assessment_id,input_cursor,? FROM deposit_monitoring_case_assessments", "0".repeat(64)));assertEquals(1,count("deposit_monitoring_case_assessments"));}
    @Test void casesHeadsAndMembershipsCannotBeRewrittenOrCleared(){inputs(customer.getId(),5);for(String table:List.of("deposit_monitoring_cases","deposit_monitoring_case_heads","deposit_monitoring_case_assessments")){String field=table.equals("deposit_monitoring_cases")?"id":"case_id";assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("UPDATE "+table+" SET "+field+"="+field));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("DELETE FROM "+table));}assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("TRUNCATE deposit_monitoring_case_assessments,deposit_monitoring_case_heads,deposit_monitoring_cases"));assertEquals(1,count("deposit_monitoring_cases"));}
    @Test void missingCaseAndAmbientTransactionsHaveNoSideEffects(){assertEquals(404,assertThrows(ResponseStatusException.class,()->cases.members(maker.user().getId(),maker.sid(),UUID.randomUUID(),null)).getStatusCode().value());assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).execute(t->cases.list(maker.user().getId(),maker.sid(),0)));assertEquals(0,count("deposit_monitoring_cases"));}
}
